('1', '1', 'Surat Tugas', 'ST-001/TU/07/2026', '2026-07-02', 'Surat Tugas', NULL, NULL, NULL, 'Upacara Bendera', '', NULL, NULL, '', NULL, NULL, NULL, NULL, NULL, 'Final', NULL, NULL, '2026-07-02 01:32:20', NULL, '{\"menimbang_a\":\"Bahwa sehubungan dengan disposisi dari Kepala Madrasah Aliyah Negeri 3 Banjar, maka dipandang perlu untuk menugaskan Aparatur Sipil Negara atau Bukan Aparatur Sipil Negara di lingkungan Madrasah Aliyah Negeri 3 Banjar.\",\"menimbang_b\":\"Bahwa untuk kepentingan dinas sebagaimana tersebut pada sub \\\"a\\\" perlu diterbitkan surat tugas dari Kepala Madrasah Aliyah Negeri 3 Banjar.\",\"dasar_surat\":\"\",\"tanggal_mulai\":\"\",\"tanggal_selesai\":\"\",\"isi_tugas\":\"\",\"penandatangan_nama\":\"a\",\"penandatangan_nip\":\"a1\",\"penandatangan_jabatan\":\"Kepala Madrasah\",\"tempat_ttd\":\"Gambut\"}');
